import React, { useEffect, useState } from 'react'
import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay } from 'swiper/modules';
import banner1 from 'assets/images/banner1.png'
import banner2 from 'assets/images/banner2.png'
import banner3 from 'assets/images/banner3.png'
import requestService from 'api/request';
import { useTranslation } from 'react-i18next';
import { useGlobalAppStore } from 'store/useGlobalApp';
import { message, Modal } from 'antd';
import { useAuthApp } from 'store/useAuthApp';
import Countdown from 'react-countdown';
const HomePage = () => {
    const [tickets, setTickets] = useState([])
    const { loading, handleLoading, handleCallbackUser } = useGlobalAppStore()
    const { user } = useAuthApp()
    const { t, i18n } = useTranslation();
    const [openConfirm, setOpenConfirm] = useState(false)
    const handleBuyTicket = async (ticketId: string) => {
        handleLoading(true)
        try {
            const res = await requestService.post('/tickets', {
                data: {
                    ticketId
                }
            })
            if (res && res.data) {
                message.success(res.data?.message)
                handleCallbackUser()
            }
        } catch (error: any) {
            message.error(error?.response?.data?.message)
        }
        handleLoading(false)
    }
    const getTickets = async () => {
        try {
            const res = await requestService.get('/tickets')
            if (res && res.data) {
                setTickets(res.data?.data)
            }
        } catch (error) {
            console.log('====================================');
            console.log(error);
            console.log('====================================');
        }
    }
    function getRandomId(existingIds: any) {
        let id;
        do {
            id = Math.floor(23000 + Math.random() * 1000); // Tạo id từ 23000 đến 23999
        } while (existingIds.has(id));
        existingIds.add(id);
        return id;
    }

    function getRandomAmount() {
        return `${Math.floor(Math.random() * 10) * 50 + 50} $`; // Bước nhảy 50$, từ 50$ đến 500$
    }

    function generateRandomObjects(count: number) {
        const objects = [];
        const existingIds = new Set();

        for (let i = 0; i < count; i++) {
            objects.push({
                id: getRandomId(existingIds),
                amount: getRandomAmount()
            });
        }

        return objects;
    }
    useEffect(() => {
        getTickets()
    }, [])
    return (
        <>
            {/* Baner */}

            <div className='h-[42vw] m-[3vw] rounded-lg overflow-hidden'
                style={{
                    boxShadow: "0 .53333vw 3.2vw #64656614"
                }}
            >
                <Swiper className="mySwiper" autoplay={{
                    delay: 2500,
                    disableOnInteraction: false,

                }}
                    loop
                    modules={[Autoplay]}
                >
                    <SwiperSlide>
                        <img src={banner2} alt='banner1' className='object-contain w-full h-full' />
                    </SwiperSlide>
                    <SwiperSlide className='object-contain w-full h-full'>
                        <img src={banner3} alt='banner1' className='object-contain w-full h-full' />
                    </SwiperSlide>
                    <SwiperSlide>
                        <img src={banner1} alt='banner1' className='object-contain w-full h-full' />
                    </SwiperSlide>
                </Swiper>
            </div>


            {/* Notice */}

            <div className='notice-bar'>
                <div className='van-notice-bar'>
                    <div className="size-6">
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="size-6">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 0 1 0 12.728M16.463 8.288a5.25 5.25 0 0 1 0 7.424M6.75 8.25l4.72-4.72a.75.75 0 0 1 1.28.53v15.88a.75.75 0 0 1-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.009 9.009 0 0 1 2.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75Z" />
                        </svg>
                    </div>
                    <div className='van-notice-bar__wrap'>
                        <Swiper autoplay={{
                            delay: 2500,
                            disableOnInteraction: false,
                        }}
                            modules={[Autoplay]}
                            direction='vertical'
                            loop={true}
                            slidesPerView={1}
                            style={{
                                height: "50px"
                            }}
                        >
                            {generateRandomObjects(30).map((item) => (
                                <SwiperSlide key={item.id} style={{
                                    height: "50px"
                                }}>
                                    <div className='h-full w-full flex
                                    items-center'>ID: {item.id} {t("home.deposit")} {item.amount}</div>
                                </SwiperSlide>
                            ))}
                        </Swiper>



                    </div>
                </div>
            </div>

            {/* quick-actions          */}
            <div data-v-caee1139="" className="quick-actions">
                <div data-v-caee1139="" className="action-item">
                    <div
                        data-v-caee1139=""
                        className="action-icon"
                        style={{ background: "rgba(25, 137, 250, 0.1)" }}
                    >
                        <svg
                            data-v-caee1139=""
                            className="inline-block"
                            viewBox="0 0 24 24"
                            width="1.2em"
                            height="1.2em"
                            style={{ color: "rgb(25, 137, 250)", width: 24, height: 24 }}
                        >
                            <path
                                fill="currentColor"
                                fillRule="evenodd"
                                d="M20.41 9.86a3 3 0 0 0-.175-.003H17.8c-1.992 0-3.698 1.581-3.698 3.643s1.706 3.643 3.699 3.643h2.433q.092.001.175-.004a1.7 1.7 0 0 0 1.586-1.581c.004-.059.004-.122.004-.18v-3.756c0-.058 0-.121-.004-.18a1.7 1.7 0 0 0-1.585-1.581m-2.823 4.611c.513 0 .93-.434.93-.971s-.417-.971-.93-.971s-.929.434-.929.971s.416.971.93.971"
