                                <div data-v-caee1139="" className="nft-image">
                                    <div data-v-caee1139="" className="van-image" style={{ width: 180 }}>
                                        <img
                                            src={`${process.env.REACT_APP_BASE_URL}` + i?.urlImage}
                                            alt="Vé vàng NFT"
                                            className="van-image__img"
                                            style={{ objectFit: "cover" }}
                                        />
                                        {/**/}
                                        {/**/}
                                    </div>
