                                                </span>
                                            </div>
                                            <div data-v-caee1139="" className="earnings-item">
                                                <span data-v-caee1139="" className="label">
                                                    {t("home.total_revenue")}
                                                </span>
                                                <span data-v-caee1139="" className="value">
                                                    {i?.price + i?.incomePerDay * i?.earningDay} $
                                                </span>
                                            </div>
                                        </div>
