                                        onClick={() => setOpenConfirm(true)}
                                        className="w-full rounded-md text-[#fff] van-button van-button--primary van-button--small van-button--block"
                                    >
                                        <div className="van-button__content">
                                            {/**/}
                                            <span className="van-button__text">
                                                {t("home.buy_now")}
                                            </span>
                                            {/**/}
                                        </div>
                                    </button>
                                </div>
                            </div>
